import React, { useState } from "react";
import { useCart } from "../components/CartContext";
import { useNavigate } from "react-router-dom";
import Checkout from "./checkout";

const modalOverlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  width: "100vw",
  height: "100vh",
  background: "rgba(0,0,0,0.35)",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  zIndex: 1000,
};
const modalBoxStyle = {
  background: "#fff",
  borderRadius: "16px",
  boxShadow: "0 8px 32px rgba(0,0,0,0.18)",
  padding: "32px 28px 24px 28px",
  minWidth: 340,
  maxWidth: 500,
  width: "90%",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  position: "relative",
};

const Cart = () => {
  const { cartItems, updateQuantity, removeFromCart } = useCart();
  const [showCheckout, setShowCheckout] = useState(false);
  const totalPrice = cartItems.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );
  const navigate = useNavigate();

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Your Cart 🛒</h2>

      {cartItems.length === 0 ? (
        <p style={styles.empty}>No items in the cart.</p>
      ) : (
        <>
          <ul style={styles.list}>
            {cartItems.map((item, index) => (
              <li key={index} style={styles.item}>
                <div style={styles.itemDetails}>
  <img
  src={`http://localhost:5000/uploads/${item.image}`}
  alt={item.name}
  style={styles.itemImage}
/>
  <div>
    <strong>{item.name}</strong>
    <p>₹{item.price} each</p>
  </div>
</div>
                <div style={styles.controls}>
                  <button
                    onClick={() =>
                      updateQuantity(item._id, Math.max(item.quantity - 1, 1))
                    }
                    style={styles.btn}
                  >
                    –
                  </button>
                  <span style={styles.qty}>{item.quantity}</span>
                  <button
                    onClick={() => updateQuantity(item._id, item.quantity + 1)}
                    style={styles.btn}
                  >
                    +
                  </button>
                </div>
                <div style={styles.remove}>
                  <button
                    onClick={() => removeFromCart(item._id)}
                    style={styles.removeBtn}
                    title="Remove from cart"
                  >
                    <svg width="20" height="20" fill="none" viewBox="0 0 24 24" stroke="var(--color-danger)" strokeWidth="2"><path d="M3 6h18M9 6v12a2 2 0 002 2h2a2 2 0 002-2V6m-6 0V4a2 2 0 012-2h2a2 2 0 012 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
                  </button>
                </div>
              </li>
            ))}
          </ul>
          <h3 style={styles.total}>Total: ₹{totalPrice}</h3>
          <button 
            style={styles.checkoutBtn}
            onClick={() => setShowCheckout(true)}
          >
            Proceed to Checkout
          </button>
          <button
            style={styles.continueBtn}
            onClick={() => navigate("/products")}
          >
            Continue Shopping 
          </button>
          {showCheckout && (
            <div style={modalOverlayStyle}>
              <div style={modalBoxStyle}>
                <Checkout onClose={() => setShowCheckout(false)} />
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: "40px",
    maxWidth: "800px",
    margin: "0 auto",
    background: "var(--color-bg)",
    borderRadius: "16px",
    boxShadow: "0 4px 16px rgba(26,35,126,0.08)",
  },
  heading: {
    fontSize: "2rem",
    marginBottom: "20px",
    color: "var(--color-primary)",
    fontWeight: 700,
  },
  empty: {
    fontSize: "18px",
    color: "var(--color-text-secondary)",
  },
  list: {
    listStyle: "none",
    padding: 0,
  },
  item: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    borderBottom: "1px solid var(--color-border)",
    padding: "15px 0",
  },
  name: {
    flex: 2,
  },
  controls: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
  },
  btn: {
    padding: "5px 12px",
    fontSize: "18px",
    cursor: "pointer",
    backgroundColor: "var(--color-primary)",
    color: "#fff",
    border: "none",
    borderRadius: "8px",
    fontWeight: 600,
    transition: "background 0.3s ease",
  },
  qty: {
    fontSize: "16px",
    fontWeight: "600",
  },
  remove: {
    marginLeft: "10px",
  },
  removeBtn: {
    backgroundColor: "transparent",
    border: "none",
    fontSize: "20px",
    cursor: "pointer",
    color: "var(--color-danger)",
  },
  total: {
    marginTop: "30px",
    fontSize: "22px",
    color: "var(--color-primary)",
    fontWeight: 700,
  },
  checkoutBtn: {
    marginTop: "15px",
    padding: "12px 24px",
    backgroundColor: "var(--color-success)",
    color: "#fff",
    fontSize: "16px",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: 600,
    transition: "background 0.3s ease",
  },
  continueBtn: {
    marginTop: "10px",
    padding: "10px 22px",
    backgroundColor: "var(--color-accent)",
    color: "#fff",
    fontSize: "15px",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: 600,
    transition: "background 0.3s ease",
    marginLeft: "10px",
  },
  itemDetails: {
    display: "flex",
    alignItems: "center",
    gap: "15px",
    flex: 2,
  },
  itemImage: {
    width: "70px",
    height: "70px",
    objectFit: "cover",
    borderRadius: "8px",
    border: "1.5px solid var(--color-border)",
    background: "var(--color-bg)",
  },
};

export default Cart;
